/* eslint-disable react/set-state-in-effect */
import React, { useCallback, useEffect, useState } from "react";
import { ArrowRight, RefreshCw } from "lucide-react";
import { Link } from "react-router-dom";
import { useAuth } from "../auth/hooks/useAuth";
import { friendlyAdminError } from "../admin/admin.errors";
import { supabase } from "../shared/lib/supabase";

type Data = { sales_today: number; sales_month: number; commission_month: number; quotes: number; orders: number; clients: number; wholesale_clients: number; goal: { objetivo: number; progreso: number; inicio: string; fin: string; alcance?: string } | null };
const money = (value: unknown) => `Q ${Number(value ?? 0).toLocaleString("es-GT", { minimumFractionDigits: 2 })}`;
const Metric: React.FC<{ label: string; value: React.ReactNode }> = ({ label, value }) => <div className="border border-gray-200 bg-white p-4"><p className="text-[11px] font-semibold uppercase tracking-wide text-gray-400">{label}</p><p className="mt-2 text-xl font-semibold">{value}</p></div>;

export const VendorAnalyticsDashboard: React.FC = () => {
  const { user, profile, sucursalActiva } = useAuth(); const [data, setData] = useState<Data | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);
  const load = useCallback(async () => { if (!user) return; setLoading(true); setError(null); const result = await supabase.rpc("obtener_dashboard_vendedor", { p_vendedor_id: user.id }); if (result.error) setError(friendlyAdminError(result.error, "No se pudo cargar el dashboard del vendedor.")); else setData((result.data ?? null) as Data | null); setLoading(false); }, [user]);
  useEffect(() => { void load(); }, [load]);
  const goal = data?.goal; const progress = goal && goal.objetivo > 0 ? Math.min(100, goal.progreso / goal.objetivo * 100) : null;
  return <section className="space-y-6"><header className="flex items-end justify-between border-b border-gray-200 pb-5"><div><p className="mb-2 text-[11px] font-semibold uppercase tracking-[0.18em] text-blue-700">Vendedor</p><h1 className="text-2xl font-semibold">Inicio</h1><p className="mt-1 text-sm text-gray-500">{profile?.nombre_completo} · {sucursalActiva?.nombre ?? "Sin sucursal"}</p></div><button type="button" title="Actualizar" onClick={() => void load()} disabled={loading} className="inline-flex items-center gap-2 border border-gray-300 px-3 py-2 text-sm disabled:opacity-50"><RefreshCw size={15} /> Actualizar</button></header>{error && <p className="border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</p>}{loading ? <p className="border border-gray-200 bg-white p-8 text-center text-sm text-gray-500">Cargando resumen...</p> : data && <><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Ventas hoy" value={money(data.sales_today)} /><Metric label="Ventas del mes" value={money(data.sales_month)} /><Metric label="Comisión generada" value={money(data.commission_month)} /><Metric label="Clientes" value={data.clients} /><Metric label="Clientes mayoristas" value={data.wholesale_clients} /><Metric label="Cotizaciones" value={data.quotes} /><Metric label="Pedidos" value={data.orders} /></div><section className="border border-gray-200 bg-white p-5"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Meta de sucursal</h2><p className="mt-1 text-sm text-gray-500">{goal ? `${goal.inicio} a ${goal.fin}` : "No hay meta asignada para este periodo."}</p></div>{progress != null && <span className="text-lg font-semibold">{progress.toFixed(1)}%</span>}</div>{goal ? <><div className="mt-4 h-3 bg-gray-100"><div className="h-3 bg-blue-600" style={{ width: `${progress}%` }} /></div><div className="mt-2 flex justify-between text-sm"><span>{money(goal.progreso)} mis ventas</span><span>{money(goal.objetivo)} meta sucursal</span></div></> : <p className="mt-4 text-sm text-amber-700">No hay meta asignada para este periodo.</p>}</section><div className="grid gap-3 sm:grid-cols-2"><Link to="/vendedor/venta" className="flex items-center justify-between bg-blue-700 p-4 text-sm font-medium text-white">Nueva venta <ArrowRight size={16} /></Link><Link to="/vendedor/cotizaciones" className="flex items-center justify-between border border-gray-200 bg-white p-4 text-sm font-medium">Cotizaciones <ArrowRight size={16} /></Link></div></>}</section>;
};
